/* 鱼数小柜台：每来一条就加一笔，随时能报总数 */
class FishCounter {
public:
    void AddFish(int fish) {
        total_fish_ = total_fish_ + fish;
    }

    int TotalFish() const {
        return total_fish_;
    }

private:
    int total_fish_ = 0;
};

int main() {
    int n = 0;
    std::cin >> n;

    FishCounter counter;
    for (int i = 0; i < n; i++) {
        int x = 0;
        std::cin >> x;
